INSERT INTO idr_core.config_federal_timeline (stage, timer_name, trigger_event, description, validation_rule, value_date, value_number, units, created_by_user, modified_by_user, provider_id, client_id) VALUES
  ('Claim Selection', 'NSA Effective Date', 'Remit Payment Date (835 remit) available', 'DOS on or after this date is ineligible', 'Must be ≥ 01-Jan-2022 (NSA enactment)', DATE '2022-01-01', NULL, 'Date', 'mock-data', 'mock-data', 1, 9101),
  ('Claim Selection', 'Claim Selection Window', 'Remit Payment Date (835 remit) available', 'Business days from remit payment date', 'Checks if remit payment date was within last configured days to be IDR eligible', NULL, 30, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('Open Negotiation', 'ON Eligible to Timed Out', 'Remit Payment Date (835 remit) available', 'Business days from remit payment date', 'Open negotiations to be sent within configured business days from remit payment date', NULL, 30, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('Open Negotiation', 'Open Negotiation Active Window', 'ONN Sent Date (Open Negotiation Start Date)', 'Business days for continuing negotiations', 'Once open negotiations are sent IDR can be filed only after the configured days', NULL, 31, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('IDR Initiation', 'IDR Initiation Filing Window- Regular', 'Open Negotiation end date for IDR cases not in cool-off', 'Business days for regular IDR cases', 'IDR an be filed within configured business days after open negotiation active wndow ends for IDR cases not in cool-off', NULL, 4, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('IDR Initiation', 'IDR Initiation Filing Window- Cool-off', 'Open Negotiation end date AND End of cool-off period', 'Business days for Cool-off impacted IDR cases', 'IDR an be filed within configured business days after open negotiation active wndow ends for IDR cases "coming out of cool-off"', NULL, 31, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('IDRE Selection', 'IDRE Assignment', 'IDR Submission Date and emails from Payers IDREs and CMS', 'Days within which IDRE needs to be finalized', 'IDRE finalization timelines. Mostly driven by Payer and IDRE acceptance. CMS will finalize the IDRE within configured business days', NULL, 3, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('IDRE Selection', 'Response to Conflict o Interest raised by IDRE', 'IDR Submission Date and emails from IDRE', 'Days within which alternate IDRE has to be selected', 'CMS provides a configured days to selecte an alterate IDRE', NULL, 1, 'Calendar Days', 'mock-data', 'mock-data', 1, 9101),
  ('Eligibility Review', 'IDRE Eligibility Determination', 'IDRE-Finalized-Assigned Date', 'Day after which eligibiliy has to be determined by IDRE', 'Driven by IDRE governs rusubmission timelines. Immediate action is expected', NULL, 0, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('IDRE Fees', 'Admin & IDRE Fee Invoicing / Payment', 'Completion of Eligibility Review', 'Days within which IDRE fees and admin fees are to be paid', 'Drvien by IDRE Due date appears on the email. Generally it is the configured days', NULL, 3, 'Calendar Days', 'mock-data', 'mock-data', 1, 9101),
  ('Offer Submission', 'Final Offer Submission', 'Fee Payment Confirmation / Eligibility Determination Date', 'Days within which offer needs to be submitted', 'Offer needs to be submitted within configured days', NULL, 10, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('Decision Determination', 'Payment Determination (Arbitrator Decision)', 'Offer submission date', 'Days within which decision is determibed', 'IDRE shall finalize the determination within the configrued days', NULL, 30, 'Business Days', 'mock-data', 'mock-data', 1, 9101),
  ('Awards & Refunds', 'Award Payment to Prevailing Party', 'Decision/Determination Date', 'Days within which 835 Awards need to be received', 'Payer shall send a new 835 within configured days', NULL, 30, 'Calendar Days', 'mock-data', 'mock-data', 1, 9101),
  ('Awards & Refunds', 'Refund Payment', 'Decision/Determination Date', 'Days within which IDRE Refundsneed to be received', 'IDRE shall send IDRE refund within the cpnfigured days', NULL, 30, 'Calendar Days', 'mock-data', 'mock-data', 1, 9101),
  ('Closed', 'Case Closure / Record Retention', 'Refund Received + Award Received', 'Days for which an IDR case need to be displayed on UI after receiving awards and refunds', 'Closed cases shall not be visible on UI but are available in database', NULL, 365, 'Calendar Days', 'mock-data', 'mock-data', 1, 9101)
