INSERT INTO idr_core.config_rarc_code (rarc_code, payment_event, description, applicable_law, federal_idr_process_eligible, created_by_user, modified_by_user, provider_id, client_id) VALUES
  ('N871', 'Initial Payment', 'Recognized amount (or air ambulance cost-sharing basis) set using a Specified State Law rate.', 'State Law Applies', false, 'mock-data', 'mock-data', 1, 9101),
  ('N877', 'Initial Payment', 'Recognized amount set as the lesser of the Qualifying Payment Amount (QPA) or billed amount; OON rate to be settled via open negotiation or Federal IDR.', 'Federal Law Applies - after Open Negotiation period completes', true, 'mock-data', 'mock-data', 1, 9101),
  ('N876', 'Notice of Denial of Payment', 'Covered item/service denied for payment; recognized amount set as lesser of QPA or billed amount; OON rate to be settled via open negotiation or Federal IDR.', 'Federal Law Applies - after Open Negotiation period completes', true, 'mock-data', 'mock-data', 1, 9101),
  ('N944', 'Notice of Denial of Payment', 'Covered item/service denied for payment; cost-sharing amount set using a Specified State Law or All-Payer Model Agreement (APMA) rate.', 'State Law / APMA Applies', false, 'mock-data', 'mock-data', 1, 9101),
  ('N872', 'Final Payment', 'Total plan/coverage (final) payment; OON rate determined under a Specified State Law.', 'State Law Applies', false, 'mock-data', 'mock-data', 1, 9101),
  ('N873', 'Final Payment', 'Total plan/coverage (final) payment; OON rate approved under an All-Payer Model Agreement (Social Security Act Sec. 1115A).', 'APMA Applies', false, 'mock-data', 'mock-data', 1, 9101),
  ('N874', 'Final Payment', 'Total plan/coverage (final) payment; OON rate is the amount agreed through Open Negotiation.', 'Federal Law Applies (Open Negotiation Outcome) - dispute already resolved', false, 'mock-data', 'mock-data', 1, 9101),
  ('N875', 'Final Payment', 'Total plan/coverage (final) payment; OON rate equals the certified IDR entity''s determination; less initial payment and cost sharing.', 'Federal Law Applies (IDR Determination)-dispute already resolved', false, 'mock-data', 'mock-data', 1, 9101),
  ('N943', 'Not Subject to NSA', 'Item/service falls outside No Surprises Act surprise billing provisions (e.g. notice-and-consent criteria satisfied).', 'Not Applicable / Excluded from NSA', false, 'mock-data', 'mock-data', 1, 9101)
